package com.intland.codebeamer.wiki.plugins.streamreuse;
import com.intland.codebeamer.persistence.dao.UserDao; import com.intland.codebeamer.persistence.dto.UserDto; import java.time.Instant; import org.springframework.stereotype.Component;
@Component
public class StreamReuseJob {
 private final UserDao users;private final StreamReuseCopyService copier;private final OperationRegistry registry;public StreamReuseJob(UserDao u,StreamReuseCopyService c,OperationRegistry r){users=u;copier=c;registry=r;}
 public void execute(int userId,StreamReuseParameters p,StreamTrackerResolver.Resolution r,StreamReusePlanner.Plan plan,StreamReuseModels.Report report){report.status=StreamReuseModels.Status.RUNNING.name();UserDto user=users.findById(userId);if(user==null){report.status=StreamReuseModels.Status.FAILED.name();report.message="Requesting user no longer exists";return;}for(StreamReusePlanner.Work w:plan.work){try{Integer id=copier.copy(user,r.targetTestRunTracker,w,report.operationId);w.result.copiedRunId=id;w.result.action="CREATED";report.createdCopies++;if(w.evidence.strategy.startsWith("EVIDENCE_INHERITED"))report.evidenceInherited++;else if(w.evidence.strategy.contains("FALLBACK"))report.evidenceFallback++;else report.evidenceImmediate++;}catch(Exception ex){w.result.action="FAILED";w.result.reason=ex.getMessage();report.failedCopies++;}}report.completedAt=Instant.now();report.status=report.failedCopies==0?StreamReuseModels.Status.COMPLETED.name():StreamReuseModels.Status.COMPLETED_WITH_ERRORS.name();report.message="Bulk operation finished. Computed-field recalculation was not requested.";}
}
